// Find this week's content row
const now = new Date();
const weekNum = Math.ceil((now - new Date(now.getFullYear(), 0, 1)) / (7 * 24 * 60 * 60 * 1000));
const rows = $input.all();

// Try to find this week's row, fall back to most recent
let thisWeek = rows.find(r => r.json.week == weekNum) || rows[rows.length - 1];

if (!thisWeek) {
  return [{ json: { error: 'No content calendar rows found', week: weekNum } }];
}

return [{
  json: {
    week: weekNum,
    content_theme: thisWeek.json.content_theme || 'Our Services',
    recent_job_example: thisWeek.json.recent_job_example || '',
    promotion_if_any: thisWeek.json.promotion_if_any || '',
    post_date: now.toISOString().split('T')[0]
  }
}];

