// Parse Claude's post content
const claudeOutput = $input.item.json.content || $input.item.json.text || $input.item.json.output || '';
let posts;
try {
  const jsonMatch = claudeOutput.match(/\{[\s\S]*\}/);
  posts = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch(e) {
  posts = { parse_error: e.message, raw: claudeOutput };
}

return {
  json: {
    ...posts,
    content_theme: $('Get This Week\'s Content').item.json.content_theme,
    post_date: $('Get This Week\'s Content').item.json.post_date
  }
};
